<?php
/**
 * LLM artifact cleaning functions.
 *
 * Removes common patterns and tics from text generated by LLMs.
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Clean LLM-generated text artifacts.
 *
 * @param string $text Raw text input.
 * @return string Cleaned text.
 */
function aif_clean_llm_artifacts( $text ) {
	$t = trim( $text );

	// Normalize line endings
	$t = str_replace( [ "\r\n", "\r" ], "\n", $t );

	// Remove common LLM opening phrases (FR + EN)
	$opening_patterns = [
		'/^\s*(bien\s+s[uû]r|bien\s+entendu|avec\s+plaisir|certainement)\s*[!:.;\-\x{2013}\x{2014}]\s*/iu',
		'/^\s*(voici|voil[aà])\s+(un|une|le|la|les|des|l\'|ce|cette|mon|ma|mes|quelques|une\s+liste)\b[^.\n]*[.:]\s*/iu',
		'/^\s*(en\s+r[eé]sum[eé]|pour\s+r[eé]sumer|en\s+conclusion|pour\s+conclure)\s*[!:.;\-\x{2013}\x{2014}]\s*/iu',
		'/^\s*(sure|of\s+course|absolutely|certainly|great\s+question)\s*[!:.;\-]\s*/iu',
		'/^\s*je\s+vais\s+vous\s+(pr[eé]senter|expliquer|montrer|d[eé]tailler)\b[^.\n]*[.:]\s*/iu',
	];
	foreach ( $opening_patterns as $p ) {
		$t = preg_replace( $p, '', $t );
	}

	// Remove common LLM closing phrases
	$closing_patterns = [
		'/\n\s*(n\'h[eé]sitez\s+pas\s+[àa]\s+me\s+(demander|contacter|solliciter|poser))[^\n]*$/iu',
		'/\n\s*(j\'esp[eè]re\s+que\s+(cela|ceci|cette|ce)\s+(vous\s+)?(aide|sera|a\s+[eé]t[eé]|r[eé]pond))[^\n]*$/iu',
		'/\n\s*(si\s+vous\s+avez\s+(d\'autres\s+)?questions)[^\n]*$/iu',
		'/\n\s*(let\s+me\s+know\s+if\s+you\s+(need|have|want))[^\n]*$/iu',
		'/\n\s*(feel\s+free\s+to\s+(ask|reach|contact))[^\n]*$/iu',
	];
	foreach ( $closing_patterns as $p ) {
		$t = preg_replace( $p, '', $t );
	}

	// Replace checklist emojis at line start with plain dash
	$t = preg_replace( '/^\s*[\x{2705}\x{2714}\x{2611}\x{1F539}\x{1F538}\x{2022}\x{25CF}\x{25CB}\x{25AA}\x{25AB}\x{27A4}\x{2B9A}]\s*/mu', '- ', $t );
	// Also catch common emoji patterns like checkmarks with variation selectors
	$t = preg_replace( '/^\s*[\x{2714}\x{FE0F}]+\s*/mu', '- ', $t );

	// Remove bold markdown markers (**text** -> text) for cleaner output
	$t = preg_replace( '/\*\*([^*]+)\*\*/', '$1', $t );

	// Remove excessive heading repetition (more than 3 consecutive headings)
	$t = preg_replace( '/((^|\n)#{1,3}\s+[^\n]+\n){4,}/u', '$0', $t );

	// Collapse 3+ blank lines into 2
	$t = preg_replace( "/\n{3,}/", "\n\n", $t );

	// Remove trailing whitespace on each line
	$t = preg_replace( '/[ \t]+$/m', '', $t );

	// Remove "Conclusion" heading if it's just a wrapper for a final paragraph
	$t = preg_replace( '/\n#{1,3}\s+(Conclusion|En conclusion|Pour conclure)\s*\n/iu', "\n", $t );

	// Remove orphan "FAQ" sections that LLMs sometimes generate
	$t = preg_replace( '/\n#{1,3}\s+(FAQ|Foire\s+aux\s+questions|Questions\s+fr[eé]quentes)\s*\n(.*\n)*?(?=\n#{1,3}\s|\z)/iu', "\n", $t );

	return trim( $t );
}
